    expected_flags = ("added", "body_changed", "renamed", "moved", "body_changed")
    for step, (event, flag) in enumerate(zip(events, expected_flags, strict=True)):
        assert isinstance(event, dict)
        assert set(event) >= {"eid", "material", "flags", "commit", "parent", "source", "destination"}
        assert event["eid"] == eid
        assert event["material"] is True
        assert isinstance(event["flags"], list)
        assert flag in event["flags"]
        assert event["commit"] == {"object_format": "sha1", "hex": fixture["commits"][step]}
        assert event["parent"] == (
            {"object_format": "sha1", "hex": fixture["commits"][step - 1]} if step else None
        )
        for endpoint, position in (("source", step - 1 if step else None), ("destination", step)):
            locator = event[endpoint]
            if position is None:
                assert locator is None
                continue
            assert isinstance(locator, dict)
            assert set(locator) >= {"id", "commit", "path_bytes_b64", "names", "span"}
            assert isinstance(locator["id"], str) and locator["id"].startswith("occ1_")
            assert locator["commit"] == {"object_format": "sha1", "hex": fixture["commits"][position]}
            assert locator["path_bytes_b64"] == b64encode(fixture["paths"][position].encode("utf-8")).decode("ascii")
            assert locator["names"] == [fixture["names"][position]]
            source = fixture["sources"][position]
            assert locator["span"] == {
                "start_byte": 0, "end_byte": len(source) - 1,
                "start_line": 1, "end_line": source.count(b"\n"),
            }


