def test_foundation_tracks_five_events_after_restart(refactor_repo):
    repo = refactor_repo["repo"]
    built = _index_cli(repo, "index", "--scope", "demo", "--ref", "HEAD", "--json")
    assert built.returncode == 0, (
        "Foundation acceptance remains RED: gita index is not implemented\n"
        f"exit={built.returncode}; stderr={built.stderr[:1200]}"
    )
    index_payload = _successful_payload(built)
    current = _successful_payload(_index_cli(repo, "id", "check_token", "--scope", "demo", "--json"))
    assert current["generation"] == index_payload["generation"]
    assert len(current["results"]) == 1
    entity_id = current["results"][0]["eid"]
    assert entity_id.startswith("eid1_")
    assert len(entity_id.removeprefix("eid1_")) == 64
    assert set(entity_id.removeprefix("eid1_")) <= set("0123456789abcdef")

    history = _successful_payload(_index_cli(
        repo, "history", entity_id, "--indexed", "--scope", "demo",
        "--order", "oldest", "--limit", "20", "--json",
    ))
    assert history["generation"] == current["generation"]
    _assert_history_events(history["results"], refactor_repo, entity_id)

    historical = _successful_payload(_index_cli(
        repo, "id", "validate_token", "--historical", "--scope", "demo", "--json",
    ))
    assert historical["generation"] == current["generation"]
    assert len(historical["results"]) == 1
    assert historical["results"][0]["eid"] == entity_id


def _f1_definition(bundle, name):
    matches = tuple(definition for definition in bundle.result.definitions
                    if not definition.synthetic_root and definition.names[-1] == name)
    assert len(matches) == 1, (name, bundle.result.definitions)
    return matches[0]


def _f1_version(bundle, definition):
    matches = tuple(version for version in bundle.versions if version.id == definition.version_id)
    assert len(matches) == 1
    return matches[0]


def _f1_assert_unknown(bundle, source, path, status):
    import hashlib

    from gita.index.model import GitOid, ParseStatus

    result = bundle.result
    assert result.status is ParseStatus(status)
    assert result.complete is False
    assert result.path == path
    assert result.byte_length == len(source)
    assert result.blob == GitOid("sha1", hashlib.sha1(
        b"blob " + str(len(source)).encode("ascii") + b"\0" + source,
    ).digest())
    assert result.definitions == ()
    assert bundle.versions == ()
    assert result.diagnostics
    assert all(type(message) is str and message for message in result.diagnostics)


